function reconcileBalances(events, initial) {
  const result = {};
  const eventMap = new Map();

  for (const event of events) {
    if (!eventMap.has(event.eventId)) {
      eventMap.set(event.eventId, event);
    }
  }

  const processedEvents = Array.from(eventMap.values());

  for (const [accountId, state] of Object.entries(initial)) {
    let currentVersion = state.version;
    let currentBalance = state.balance;
    let stopped = false;

    while (!stopped) {
      const targetVersion = currentVersion + 1;
      const nextEvents = processedEvents.filter(
        e => e.accountId === accountId && e.version === targetVersion
      );

      if (nextEvents.length === 0) {
        stopped = true;
        continue;
      }

      if (nextEvents.length > 1) {
        stopped = true;
        continue;
      }

      const event = nextEvents[0];
      currentVersion = targetVersion;
      currentBalance += event.delta;
    }

    result[accountId] = { balance: currentBalance, version: currentVersion };
  }

  return result;
}

